const A='assets/';const I={shelves:A+'01-interior-shelves.png',ramenRoom:A+'02-ramen-room.png',wide:A+'03-store-wide.png',productWall:A+'04-product-wall.png',ramen:A+'05-ramen-bar.png',entrance:A+'06-entrance.png',keychains:A+'07-keychains.png',kpop:A+'08-kpop-shelves.png',flower:A+'09-interior-flower.png',logo:A+'10-ktown-logo.jpg'};const MAP='https://maps.app.goo.gl/CDE7RZ4BGexHf3NYA';
document.querySelector('#root').innerHTML=`<div class="site"><div class="concept-bar"><span>CONCEPT / DEMO WEBSITE</span><span>Designed for K Town · not officially commissioned</span></div><header class="nav"><a class="nav-brand" href="#arrival"><img class="brand-logo" src="${I.logo}" alt="K Town logo"></a><nav class="nav-links"><a href="#arrival">Arrival</a><a href="#experience">Explore</a><a href="#shop">Shop</a><a href="#taste">Taste</a><a href="#discover">Discover</a><a href="#community">Community</a><a href="#visit">Visit</a><a class="nav-visit" href="${MAP}" target="_blank" rel="noreferrer">Directions ↗</a></nav><button class="menu-btn" aria-label="Menu">☰</button></header><main>
<section id="arrival" class="hero section-shell"><div class="hero-copy reveal"><div class="eyebrow">SEOUL ENERGY · SILIGURI ADDRESS</div><h1>A LITTLE PIECE OF <em>KOREA.</em><br>RIGHT HERE IN <span>SILIGURI.</span></h1><p>Step into K Town — a Korean culture, lifestyle and food destination inside Vega Circle Mall.</p><div class="hero-actions"><a class="btn btn-dark" href="#experience">Explore K Town ↓</a><a class="btn btn-light" href="${MAP}" target="_blank" rel="noreferrer">Get directions ⌖</a></div><div class="hero-micro"><span>● Vega Circle Mall</span><span>Sevoke Road · Siliguri</span></div></div><div class="hero-visual reveal"><div class="hero-frame"><img class="hero-image" src="${I.entrance}" alt="K Town exterior entrance"></div><button class="hero-sticker collectible" data-fragment="안녕하세요"><span>안녕하세요</span><small>WELCOME</small></button><div class="hero-index">01 / 07</div></div></section>
<section id="experience" class="experience section-shell"><div class="section-top reveal"><div><div class="eyebrow">THE EXPERIENCE</div><h2>Not a stop.<br><i>A small journey.</i></h2></div><p>Follow the feeling. Choose a path, then let the store pull you somewhere unexpected.</p></div><div class="experience-grid"><button class="experience-card" data-intent="Shopping"><b>01</b><strong>SHOP</strong><span>See what’s on the shelves ↗</span><img data-parallax="10" src="${I.shelves}" alt="K Town shelves"></button><button class="experience-card" data-intent="Food"><b>02</b><strong>EAT</strong><span>Build a bowl ↗</span><img data-parallax="8" src="${I.ramenRoom}" alt="K Town ramen area"></button><button class="experience-card" data-intent="Explore"><b>03</b><strong>DISCOVER</strong><span>Find your tiny Seoul moment ↗</span><img data-parallax="12" src="${I.keychains}" alt="Korean-inspired accessories at K Town"></button></div></section>
<section class="intent-strip"><div class="eyebrow">WHAT ARE YOU HERE FOR?</div><div class="intent-row">${['K-Pop','Food','Shopping','Gifts','Explore'].map(x=>`<button data-intent="${x}">${x}<span>↗</span></button>`).join('')}</div><div class="intent-result"><div><small id="intent-kicker">EXPLORE / K TOWN</small><h3 id="intent-title">Shop. Eat. Discover.</h3><p id="intent-body">Your route through a Korean-inspired retail and food destination in Siliguri.</p></div><a class="text-link" href="#discover">Take me there →</a></div></section>
<section id="shop" class="world-section"><div class="world-head section-shell reveal"><div class="eyebrow">03 / SHOP</div><h2>The shelves are<br><i>part of the story.</i></h2><p>Real K Town imagery, arranged like an editorial lookbook. No invented catalogue—just a sense of what it feels like inside.</p></div><div class="pin-track"><div class="pin-panel">${[[I.kpop,'K-Pop','albums · lightsticks'],[I.productWall,'Everyday discovery','snacks · pantry · gifting'],[I.keychains,'Details','small finds · playful details'],[I.wide,'The room','colour · shelves · movement']].map((x,i)=>`<article class="look-card"><div class="look-index">0${i+1}</div><img src="${x[0]}" alt="${x[1]}"><div class="look-caption"><strong>${x[1]}</strong><span>${x[2]}</span></div></article>`).join('')}</div></div></section>
<section id="taste" class="ramen-section section-shell"><div class="ramen-copy reveal"><div class="eyebrow">04 / TASTE · RAMEN</div><h2>Your bowl.<br><i>Your rules.</i></h2><p>The supplied store imagery shows a self-serve ramen setup where ingredients can be combined into a bowl. This interaction is a concept layer until menu/pricing data is verified.</p><div class="bowl-controls"><label>Base<select id="base"><option>Buldak Chicken Carbonara</option><option>Ramen — verify on visit</option></select></label><label>Topping<select id="top"><option>Cheese</option><option>Egg</option><option>Vegetables</option></select></label><label>Finish<select id="finish"><option>Spring onion</option><option>Greens</option></select></label></div><div class="bowl-note">✦ Demo build — not an ordering flow.</div></div><div class="bowl-stage reveal"><div class="bowl-blob"></div><img data-parallax="8" src="${I.ramen}" alt="Self-serve ramen toppings at K Town"><div class="annotation ann1"><span>01</span><b id="a1">Buldak Chicken Carbonara</b></div><div class="annotation ann2"><span>02</span><b id="a2">Cheese</b></div><div class="annotation ann3"><span>03</span><b id="a3">Spring onion</b></div></div></section>
<section id="discover" class="culture section-shell"><div class="culture-image reveal"><img src="${I.flower}" alt="K Town interior ceiling installation"></div><div class="culture-copy reveal"><div class="eyebrow">05 / DISCOVER · CULTURE</div><h2>A slice of Seoul,<br><i>in Siliguri.</i></h2><p>K Town’s atmosphere is part of the destination: soft pink architecture, floral ceilings, Korean signage, colourful shelves and the feeling of finding something new.</p><div class="fragment-board"><button class="collectible" data-fragment="SHOPPING LABEL">SHOPPING LABEL ↗</button><button class="collectible" data-fragment="라면 · RAMEN">라면 · RAMEN ↗</button><button class="collectible" data-fragment="서울 · SEOUL">서울 · SEOUL ↗</button><button class="collectible" data-fragment="DISCOVERY">DISCOVERY ↗</button></div></div></section>
<section id="community" class="community section-shell"><div class="section-top reveal"><div><div class="eyebrow">06 / COMMUNITY</div><h2>Heard from<br><i>people who went.</i></h2></div><p>Only review text visible on the supplied Google listing is used here. Nothing below is presented as a brand-authored testimonial.</p></div><div class="reviews">${[['A slice of Seoul right here in Siliguri!','Aditi Jaiswal'],['The place for Korean culture experience... KPOP ALBUMS and LIGHTSTICKS!','Shinjan Biswas'],['I really enjoyed my visit there; I bought a BTS kit...','Depe Goldar']].map((r,i)=>`<article class="review reveal"><div class="review-top"><span>0${i+1}</span><span>★★★★★</span></div><blockquote>“${r[0]}”</blockquote><div class="review-name">${r[1]}</div><small>Google review · visible on the supplied listing</small></article>`).join('')}</div></section>
<section id="visit" class="visit section-shell"><div class="visit-card reveal"><div><div class="eyebrow">07 / VISIT</div><h2>Come experience<br><i>K Town.</i></h2><p>Vega Circle Mall, Sevoke Rd,<br>Ward 42, Siliguri, West Bengal 734008</p><a class="btn btn-dark" href="${MAP}" target="_blank" rel="noreferrer">Open in Maps ⌖</a></div><div class="visit-photo"><img src="${I.entrance}" alt="K Town exterior"><div class="map-label">VEGA CIRCLE MALL<br><span>SILIGURI</span></div></div></div><div class="hours-row"><div><span>Status shown on supplied listing</span><strong>Open · Closes 10 pm</strong></div><div class="hours-note">Hours may change. Verify on the day of your visit.</div></div></section>
<section class="final section-shell"><div class="final-orbit"><img src="${I.logo}" alt="K Town logo"></div><div class="eyebrow">SHOP · EAT · DISCOVER</div><h2>COME EXPERIENCE<br><i>K TOWN.</i></h2><div class="hero-actions"><a class="btn btn-dark" href="#arrival">Explore ↓</a><a class="btn btn-light" href="${MAP}" target="_blank" rel="noreferrer">Directions ⌖</a></div></section></main><footer><img class="brand-logo" src="${I.logo}" alt="K Town logo"><div>KETOWN · A LITTLE PIECE OF KOREA, RIGHT HERE IN SILIGURI.</div><a href="#arrival">Back to top ↑</a></footer><div class="fragment-toast" hidden><span>DISCOVERED</span><strong></strong></div></div>`;

gsap.registerPlugin(ScrollTrigger);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduced){document.querySelectorAll('[data-parallax]').forEach(el=>gsap.to(el,{yPercent:-(+el.dataset.parallax||10),ease:'none',scrollTrigger:{trigger:el,start:'top bottom',end:'bottom top',scrub:true}}));document.querySelectorAll('.reveal').forEach(el=>gsap.fromTo(el,{y:28,opacity:0},{y:0,opacity:1,duration:.8,ease:'power2.out',scrollTrigger:{trigger:el,start:'top 86%',once:true}}));const track=document.querySelector('.pin-track'),panel=document.querySelector('.pin-panel');gsap.to(panel,{x:()=>-(panel.scrollWidth-track.clientWidth+40),ease:'none',scrollTrigger:{trigger:track,start:'top top',end:()=>'+='+Math.max(900,panel.scrollWidth-track.clientWidth+40),pin:true,scrub:1,invalidateOnRefresh:true}});gsap.to('.hero-image',{scale:1.08,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:true}})}
const data={Explore:['EXPLORE / K TOWN','Shop. Eat. Discover.','Your route through a Korean-inspired retail and food destination in Siliguri.'],Shopping:['SHOP / DISCOVER','Small finds, big Seoul energy.','A visual introduction to the shelves and store atmosphere.'],Food:['FOOD / TASTE','Make a bowl, make it yours.','A demonstrational ramen interaction inspired by the supplied store imagery.'],'K-Pop':['K-POP / COLLECT','Albums, lightsticks & culture-led finds.','Explore the K-Pop side of K Town through real store imagery.'],Gifts:['GIFTS / LITTLE THINGS','A tiny piece of Korea to take home.','Giftable details shown as inspiration, not a live inventory.']};document.querySelectorAll('[data-intent]').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.intent;document.querySelectorAll('.intent-row button').forEach(x=>x.classList.toggle('active',x.dataset.intent===k));const d=data[k];document.querySelector('#intent-kicker').textContent=d[0];document.querySelector('#intent-title').textContent=d[1];document.querySelector('#intent-body').textContent=d[2]}));['base','top','finish'].forEach((id,i)=>document.getElementById(id).addEventListener('change',e=>document.querySelector('#a'+(i+1)).textContent=e.target.value));document.querySelector('.menu-btn').addEventListener('click',()=>document.querySelector('.nav-links').classList.toggle('open'));document.querySelectorAll('.collectible').forEach(b=>b.addEventListener('click',()=>{const t=document.querySelector('.fragment-toast');t.hidden=false;t.querySelector('strong').textContent=b.dataset.fragment;clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.hidden=true,1800)}));
